export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"emotions-motivate-and-organize-us-for-action-e5dbb1bb24d5\",\"title\":\"Emotions Motivate (and Organize) Us for Action\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9694],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/04-dbt-emotion-regulation-emotion-regulation-handout-3-emotions-motivate-and-organize-us-for-5c72402d6e.json\",\"sha256\":\"5c72402d6e980a547dbdc5527520e060445bcd412d178506f086f3c8595b9aca\",\"domain\":\"dbt\",\"bytes\":5597},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/emotion-regulation-handout-3-emotions-motivate-and-organize-us-for-action-21d7ad38fc.json\",\"sha256\":\"21d7ad38fc59c76f2591359a843d77569c7af23e22dfbf30c6f3240c6d4fce86\",\"domain\":\"dbt\",\"bytes\":5446}]},\"data\":{\"pages\":[{\"pdf_page\":234,\"book_page\":\"210\",\"text\":\"210\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nEmotion Regulation Handout 3   (Emotion Regulation Worksheets 2, 2a\u2013c)\\nWhat Emotions Do for You\\nEmotions Motivate (and Organize) Us for Action\\n\u2022\u2022 Emotions motivate our behavior. Emotions prepare us for action.\\nThe action urge of specific emotions is often \u201chard-wired\u201d in biology.\\n\u2022\u2022 Emotions save time in getting us to act in important situations.\\nEmotions can be especially important when we don\u2019t have time to think things through.\\n\u2022\u2022 Strong emotions help us overcome obstacles\u2014in our minds and in the environment.\\nEmotions Communicate to (and Influence) Others\\n\u2022\u2022 Facial expressions are hard-wired aspects of emotions.\\nFacial expressions communicate faster than words.\\n\u2022\u2022 Our body language and voice tone can also be hard-wired.\\nLike it or not, they also communicate our emotions to others.\\n\u2022\u2022 When it is important to communicate to others, or send them a message,\\nit can be very hard to change our emotions.\\n\u2022\u2022 Whether we intend it or not, our communication of emotions influences others.\\nEmotions Communicate to Ourselves\\n\u2022\u2022 Emotional reactions can give us important information about a situation.\\nEmotions can be signals or alarms that something is happening.\\n\u2022\u2022 Gut feelings can be like intuition\u2014a response to something important about the situation.\\nThis can be helpful if our emotions get us to check out the facts.\\n\u2022\u2022 Caution: Sometimes we treat emotions as if they are facts about the world: The stronger\\nthe emotion, the stronger our belief that the emotion is based on fact. (Examples: \u201cIf I feel\\nunsure, I am incompetent,\u201d \u201cIf I get lonely when left alone, I shouldn\u2019t be left alone,\u201d \u201cIf I feel\\nconfident about something, it is right,\u201d \u201cIf I\u2019m afraid, there must be danger,\u201d \u201cI love him, so\\nhe must be OK.\u201d)\\n\u2022\u2022 If we assume that our emotions represent facts about the world, we may use them to justify\\nour thoughts or our actions. This can be trouble if our emotions get us to ignore the facts.\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Emotion Regulation Handout 3   (Emotion Regulation Worksheets 2, 2a\u2013c)\",\"source_pdf_pages\":[234],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/emotion_regulation/handouts/emotion_regulation_handout_3_emotions_motivate_and_organize_us_for_action.json\",\"item_number\":\"3\",\"full_text\":\"Emotion Regulation Handout 3   (Emotion Regulation Worksheets 2, 2a\u2013c)\\nWhat Emotions Do for You\\nEmotions Motivate (and Organize) Us for Action\\n\u2022\u2022 Emotions motivate our behavior. Emotions prepare us for action.\\nThe action urge of specific emotions is often \u201chard-wired\u201d in biology.\\n\u2022\u2022 Emotions save time in getting us to act in important situations.\\nEmotions can be especially important when we don\u2019t have time to think things through.\\n\u2022\u2022 Strong emotions help us overcome obstacles\u2014in our minds and in the environment.\\nEmotions Communicate to (and Influence) Others\\n\u2022\u2022 Facial expressions are hard-wired aspects of emotions.\\nFacial expressions communicate faster than words.\\n\u2022\u2022 Our body language and voice tone can also be hard-wired.\\nLike it or not, they also communicate our emotions to others.\\n\u2022\u2022 When it is important to communicate to others, or send them a message,\\nit can be very hard to change our emotions.\\n\u2022\u2022 Whether we intend it or not, our communication of emotions influences others.\\nEmotions Communicate to Ourselves\\n\u2022\u2022 Emotional reactions can give us important information about a situation.\\nEmotions can be signals or alarms that something is happening.\\n\u2022\u2022 Gut feelings can be like intuition\u2014a response to something important about the situation.\\nThis can be helpful if our emotions get us to check out the facts.\\n\u2022\u2022 Caution: Sometimes we treat emotions as if they are facts about the world: The stronger\\nthe emotion, the stronger our belief that the emotion is based on fact. (Examples: \u201cIf I feel\\nunsure, I am incompetent,\u201d \u201cIf I get lonely when left alone, I shouldn\u2019t be left alone,\u201d \u201cIf I feel\\nconfident about something, it is right,\u201d \u201cIf I\u2019m afraid, there must be danger,\u201d \u201cI love him, so\\nhe must be OK.\u201d)\\n\u2022\u2022 If we assume that our emotions represent facts about the world, we may use them to justify\\nour thoughts or our actions. This can be trouble if our emotions get us to ignore the facts.\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Emotion Regulation Worksheets 2, 2a\u2013c\"],\"id\":\"emotion_regulation_handout_3\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"210\"],\"title\":\"Emotions Motivate (and Organize) Us for Action\",\"module_category\":\"Emotion Regulation Skills\",\"shared_json_path\":\"shared/04_dbt_emotion_regulation/handouts_json/emotion_regulation_handout_3_emotions_motivate_and_organize_us_for_action.json\",\"module\":\"Emotion Regulation\",\"keywords\":[\"Action\",\"Emotions\",\"Motivate\",\"Organize\"]}}");
